"""Resolve company mentions to entities: ticker, then legal name, then alias.

The order of the rules is part of the answer. A ticker match is tried on the
raw surface (with an optional leading $ for cashtags) BEFORE normalisation,
because normalisation would destroy the difference between "GM" the ticker
and "gm" the word. Then the normalised surface is compared with normalised
legal names and aliases together: if that key belongs to more than one entity
(e.g. an alias two companies share) the mention is ambiguous, whatever rule
would otherwise have claimed it.

Normalisation drops legal-form suffixes so "Microsoft Corp." and "Microsoft
Corporation" meet on "microsoft".
"""
import json
import os
import re

import pandas as pd

DATA = "/input/environment/data"
OUT_DIR = "/app/output"
DROP = {"inc", "incorporated", "corp", "corporation", "co", "company", "ltd", "plc", "llc", "the"}


def norm(s: str) -> str:
    tokens = re.sub(r"[^a-z0-9 ]", " ", str(s).lower()).split()
    return " ".join(t for t in tokens if t not in DROP)


def main() -> None:
    entities = pd.read_csv(f"{DATA}/entities.csv", keep_default_na=False)
    mentions = pd.read_csv(f"{DATA}/mentions.csv", keep_default_na=False)

    by_ticker = {str(t).upper(): e for e, t in zip(entities["entity_id"], entities["ticker"])}
    by_name: dict[str, set] = {}
    by_alias: dict[str, set] = {}
    for row in entities.itertuples(index=False):
        by_name.setdefault(norm(row.legal_name), set()).add(row.entity_id)
        for alias in str(row.aliases).split(";"):
            if alias.strip():
                by_alias.setdefault(norm(alias), set()).add(row.entity_id)

    resolved = []
    for m in mentions.itertuples(index=False):
        raw = str(m.surface).strip()
        cashtag = raw[1:] if raw.startswith("$") else raw
        key = norm(m.surface)
        candidates = by_name.get(key, set()) | by_alias.get(key, set())
        if cashtag.upper() in by_ticker:
            entity, rule = by_ticker[cashtag.upper()], "ticker"
        elif key and len(candidates) > 1:
            entity, rule = "", "ambiguous"
        elif key and len(by_name.get(key, set())) == 1:
            entity, rule = next(iter(by_name[key])), "legal_name"
        elif key and len(by_alias.get(key, set())) == 1:
            entity, rule = next(iter(by_alias[key])), "alias"
        else:
            entity, rule = "", "none"
        resolved.append({"mention_id": m.mention_id, "entity_id": entity, "rule": rule})

    out = pd.DataFrame(resolved)
    summary = {
        "n_mentions": int(len(out)),
        "n_resolved": int((out["entity_id"] != "").sum()),
        "n_ambiguous": int((out["rule"] == "ambiguous").sum()),
        "mentions_per_entity": {e: int((out["entity_id"] == e).sum()) for e in entities["entity_id"]},
    }
    os.makedirs(OUT_DIR, exist_ok=True)
    out.to_csv(os.path.join(OUT_DIR, "resolved.csv"), index=False)
    with open(os.path.join(OUT_DIR, "resolution_summary.json"), "w", encoding="utf-8") as fh:
        json.dump(summary, fh, indent=2)
    print(summary)


if __name__ == "__main__":
    main()
